-- Rollback of migration 002 (worker_pipeline), generated by focus.migrations.rollback_script from the forward
-- script's declared objects. Recovery is forward by default; this exists for an install that has just failed review.
-- The runner executes it in one transaction under sp_getapplock('FOCUS_FN_MIGRATIONS'); any guard stops it whole.
-- Nothing here deletes a row.
SET XACT_ABORT ON;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_Outbox_AppendOnly;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_Outbox) THROW 51951, 'WEB_APP.FOCUS_FN_Outbox holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_Outbox;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_PipelineStep) THROW 51952, 'WEB_APP.FOCUS_FN_PipelineStep holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_PipelineStep;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_PipelineRun) THROW 51953, 'WEB_APP.FOCUS_FN_PipelineRun holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_PipelineRun;
DROP INDEX IF EXISTS IX_FN_WorkerRun_Queue ON WEB_APP.FOCUS_FN_WorkerRun;
ALTER TABLE WEB_APP.FOCUS_FN_WorkerRun DROP CONSTRAINT IF EXISTS CK_FN_WorkerRun_Lease;
ALTER TABLE WEB_APP.FOCUS_FN_WorkerRun DROP CONSTRAINT IF EXISTS CK_FN_WorkerRun_Status;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_WorkerRun WHERE FinishedAtUtc IS NOT NULL) THROW 51954, 'WEB_APP.FOCUS_FN_WorkerRun.FinishedAtUtc holds values; recover forward with a new migration', 1;
ALTER TABLE WEB_APP.FOCUS_FN_WorkerRun DROP COLUMN IF EXISTS FinishedAtUtc;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_WorkerRun WHERE CreatedAtUtc IS NOT NULL) THROW 51955, 'WEB_APP.FOCUS_FN_WorkerRun.CreatedAtUtc holds values; recover forward with a new migration', 1;
ALTER TABLE WEB_APP.FOCUS_FN_WorkerRun DROP COLUMN IF EXISTS CreatedAtUtc;
ALTER TABLE WEB_APP.FOCUS_FN_WorkerRun DROP CONSTRAINT IF EXISTS CK_FN_WorkerRun_Attempts;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_WorkerRun WHERE Attempts IS NOT NULL) THROW 51956, 'WEB_APP.FOCUS_FN_WorkerRun.Attempts holds values; recover forward with a new migration', 1;
ALTER TABLE WEB_APP.FOCUS_FN_WorkerRun DROP COLUMN IF EXISTS Attempts;
ALTER TABLE WEB_APP.FOCUS_FN_WorkerRun DROP CONSTRAINT IF EXISTS CK_FN_WorkerRun_Role;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_WorkerRun WHERE Role IS NOT NULL) THROW 51957, 'WEB_APP.FOCUS_FN_WorkerRun.Role holds values; recover forward with a new migration', 1;
ALTER TABLE WEB_APP.FOCUS_FN_WorkerRun DROP COLUMN IF EXISTS Role;
